-- Harden nullable rowid-table primary keys without rewriting retained evidence.
PRAGMA user_version = 2;
CREATE TRIGGER pk_artifact_insert BEFORE INSERT ON artifact WHEN NEW.id IS NULL BEGIN SELECT RAISE(ABORT,'null relational identity'); END;
CREATE TRIGGER pk_artifact_update BEFORE UPDATE ON artifact WHEN NEW.id IS NULL BEGIN SELECT RAISE(ABORT,'null relational identity'); END;
