CREATE TRIGGER typed_level_update BEFORE UPDATE ON factor_level WHEN NEW.kind != (SELECT kind FROM factor WHERE id=NEW.factor_id) BEGIN SELECT RAISE(ABORT,'factor kind mismatch'); END;
CREATE TRIGGER fixed_attempt_condition BEFORE UPDATE ON attempt WHEN NEW.trial_id!=OLD.trial_id OR NEW.number!=OLD.number OR NEW.driver_sha256!=OLD.driver_sha256 OR NEW.condition_sha256!=OLD.condition_sha256 OR NEW.command_json!=OLD.command_json BEGIN SELECT RAISE(ABORT,'immutable attempt condition'); END;
CREATE TRIGGER fixed_resource_owner BEFORE UPDATE ON resource WHEN NEW.token!=OLD.token OR NEW.daemon_id!=OLD.daemon_id OR NEW.container_name!=OLD.container_name OR NEW.volume_name!=OLD.volume_name OR (OLD.container_id IS NOT NULL AND NEW.container_id IS NOT OLD.container_id) OR (OLD.created_at IS NOT NULL AND NEW.created_at IS NOT OLD.created_at) OR (OLD.started_at IS NOT NULL AND NEW.started_at IS NOT OLD.started_at) BEGIN SELECT RAISE(ABORT,'immutable process-tree identity'); END;
